/* @autogenerated */
import { inject, Injectable } from '@angular/core';
import { trace, Tracer } from '@opentelemetry/api';
import { RuntimeConfigService } from '@shared/context/config/app-config.service';
import { AppStateService } from '@shared/context/state/app-state.service';
import { environment } from 'app/bootstrap/environment/environment';
import { NavigationEnd, Router } from '@angular/router';
import { firstValueFrom, Subscription } from 'rxjs';
import { Logger } from './logger.service';

@Injectable({ providedIn: 'root' })
export class InstrumentationService {
  private readonly router = inject(Router);
  private readonly config = inject(RuntimeConfigService);
  private readonly logger = inject(Logger);
  private readonly appState = inject(AppStateService);

  private tracerMap = new Map<string, Tracer>();
  private activated = false;
  private routerSubscription?: Subscription;
  private currentTenant?: string;

  public getTracer(name: string = 'default'): Tracer {
    if (!this.tracerMap.has(name)) {
      this.tracerMap.set(name, trace.getTracer(name));
    }
    return this.tracerMap.get(name)!;
  }

  public startSpan(name: string, tracerName = 'default', attributes: Record<string, any> = {}) {
    const tracer = this.getTracer(tracerName);
    const span = tracer.startSpan(name, { attributes });
    return span;
  }

  public async activate(): Promise<void> {
    if (this.activated) {
      return;
    }
    this.activated = true;
    const conf = await firstValueFrom(this.config.value$('telemetry'));
    if (!conf?.name) {
      this.logger.debug('Telemetry disabled: add telemetry.name to the config');
      return;
    }
    try {
      const { startTelemetry } = await import('./otel-bootstrap');
      this.appState.tenant$.subscribe((tenant) => (this.currentTenant = tenant));
      const { logSink } = startTelemetry(conf, {
        version: environment.version,
        sessionId: tabSessionId(),
        tenant: () => this.currentTenant,
      });
      if (logSink) {
        this.logger.attachRemote(logSink);
        // Por defecto solo sale lo que pasa por Logger: console.* puede llevar datos de cualquier librería
        if (conf.logger?.['capture-console'] === true) {
          this.logger.captureConsole();
        }
      }
    } catch (error) {
      this.logger.error('Unable to start telemetry', error);
    }
    this.registerRouter(trace.getTracer('angular-router'));
  }

  private registerRouter(routeTracer: Tracer) {
    if (this.routerSubscription) {
      return;
    }
    this.routerSubscription = this.router.events.subscribe((event) => {
      if (event instanceof NavigationEnd) {
        const span = routeTracer.startSpan('navigation', {
          attributes: {
            'route.path': event.urlAfterRedirects,
          },
        });
        span.end();
      }
    });
  }
}

const SESSION_KEY = 'telemetry-session-id';

/** Aleatorio por pestaña: sessionStorage sobrevive a recargas pero no se comparte entre pestañas. */
export function tabSessionId(): string {
  let id = sessionStorage.getItem(SESSION_KEY);
  if (!id) {
    // randomUUID solo existe en contextos seguros (https o localhost)
    id =
      typeof crypto.randomUUID === 'function'
        ? crypto.randomUUID()
        : Array.from(crypto.getRandomValues(new Uint8Array(16)), (b) => b.toString(16).padStart(2, '0')).join('');
    sessionStorage.setItem(SESSION_KEY, id);
  }
  return id;
}
